    {
      id: 2,
      title: "DogeFake",
      ticker: "DFAKE",
      address: NEW_DOGEFAKE_ADDRESS,
      abi: DogeFake.abi,
    },
  ];

  return (
    <ModalWrapper
      isVisible={isVisible}
      onClose={onClose}
      title="Get Faucet Tokens"
    >
      <div className="p-2 relative z-10 rounded">
        {tokens.map((token) => (
          <div
            key={token.id}
            className="flex justify-around items-center font-mono py-2"
          >
            <button
              disabled={loading}
              className="bg-black p-2 px-4 rounded-md hover:bg-[#016244]"
              onClick={() =>
                addTokenFaucetToWallet(
                  token.id,
                  token.ticker,
                  token.address,
                  token.abi
                )
              }
            >
              {loading === token.id
                ? "Sending token..."
                : `Send me ${token.ticker}`}
            </button>
          </div>
        ))}
      </div>
    </ModalWrapper>
  );
};

export default ModalFaucet;
